// recipe: input-methods
// args: none
// serves: cross-player-eat-skips-native-steps (the key patch targets are not the names Unity's Input actually declares)
// returns: ok, count, methods, error, detail
//
// Every method `UnityEngine.Input` declares whose name contains "Key", with its parameter list and whether it has an IL body: the PATCH TARGETS have to
// be read from the build, not remembered (2026-10-28: `GetKeyInt`/`GetKeyDownInt`/`GetKeyUpInt` answered "no method on this build", and the KeyCode
// wrappers are inlinable, so the real entry points had to be enumerated).
((System.Func<string>)(() => { try { System.Type inputType = null; var asms = System.AppDomain.CurrentDomain.GetAssemblies(); for (var i = 0; i < asms.Length && inputType == null; i++) { inputType = asms[i].GetType("UnityEngine.Input"); } if (inputType == null) { return "{\"ok\":false,\"error\":\"no-Input\"}"; } const System.Reflection.BindingFlags F = System.Reflection.BindingFlags.Static | System.Reflection.BindingFlags.Public | System.Reflection.BindingFlags.NonPublic | System.Reflection.BindingFlags.DeclaredOnly; var methods = inputType.GetMethods(F); var parts = new System.Collections.Generic.List<string>(); for (var m = 0; m < methods.Length; m++) { var method = methods[m]; if (method.Name.IndexOf("Key", System.StringComparison.Ordinal) < 0) { continue; } var parameters = method.GetParameters(); var signature = method.Name + "("; for (var p = 0; p < parameters.Length; p++) { signature += (p > 0 ? "," : "") + parameters[p].ParameterType.Name; } signature += ")"; var body = "managed"; try { if (method.GetMethodBody() == null) { body = "no-IL"; } } catch { body = "no-IL"; } parts.Add(signature + ":" + body); } return "{\"ok\":true,\"count\":" + parts.Count + ",\"methods\":\"" + string.Join(" | ", parts) + "\"}"; } catch (System.Exception e) { return "{\"ok\":false,\"error\":\"read-failed\",\"detail\":\"" + e.GetType().Name + ": " + e.Message.Replace("\\", " ").Replace("\"", "'") + "\"}"; } }))()
